  // 4. Image loader helper
  async function m_loadImage(url) {
    let fullUrl = url.startsWith('http') || url.startsWith('/') || url.startsWith('./') ? url : (__assetBaseUrl + url);
    let img = new Image();
    img.decoding = "async";
    await new Promise((resolve, reject) => {
      img.onload = () => resolve(img);
      img.onerror = () => {
        console.warn("Could not load image:", fullUrl);
        resolve(img);
      };
      img.src = fullUrl;
    });
    return img;
  }

  const m = m_loadImage;

